package io.github.luckolite.interpreter;import java.nio.file.*;import java.io.*;import java.util.*;/** Independent original/reference/quotas, no semantic admission or Source call. */public class EighthHelperControls {    static int checks;    static void check(boolean b, String s) {        checks++;        if (!b) throw new AssertionError(s);    }    record Input(byte[] raw, int w, int h, SixteenthRestDetector.Staff frame) {}    static Input read(Path f) throws Exception {        try (var in = new DataInputStream(Files.newInputStream(f))) {            int w = in.readInt(), h = in.readInt();            float t = in.readFloat(), b = in.readFloat(), g = in.readFloat();            return new Input(                    in.readNBytes(w * h), w, h, new SixteenthRestDetector.Staff(t, b, g, 0, 1));        }    }    static boolean[] rules(Input a, boolean narrow) {        boolean[] out = new boolean[a.h];        float g = a.frame.gap();        for (int y = 0; y < a.h; y++) {            float near = a.frame.top() + Math.round((y - a.frame.top()) / g) * g;            int run = 0, longest = 0, n = 0, threshold = narrow ? 170 : 230;            for (int x = 0; x < a.w; x++)                if ((a.raw[y * a.w + x] & 255) < threshold) {                    n++;                    longest = Math.max(longest, ++run);                } else run = 0;            out[y] =                    Math.abs(y - near) <= g * (narrow ? .2f : .35f)                            && (n > a.w * .25f || longest >= g * 5);        }        return out;    }    static FaintEighthRestInk.Proof prove(Input a, int l, int r, FaintQuarterRestInk.Budget b) {        return FaintEighthRestInk.prove(                a.raw, a.w, a.h, a.frame, l, r, 0, rules(a, true), rules(a, false), b);    }    static void quotas(            Input a, int l, int r, FaintEighthRestInk.Proof expected, long work, long bytes) {        var exact = new FaintQuarterRestInk.Budget(work, bytes);        var p = prove(a, l, r, exact);        check(                p != null                        && p.l == expected.l                        && p.t == expected.t                        && p.r == expected.r                        && p.b == expected.b,                "exact physical bound");        check(exact.workUsed == work && exact.bytesUsed == bytes, "exact counters");        for (int mode = 0; mode < 2; mode++) {            var low =                    new FaintQuarterRestInk.Budget(                            work - (mode == 0 ? 1 : 0), bytes - (mode == 1 ? 1 : 0));            boolean refused = false;            try {                prove(a, l, r, low);            } catch (FaintQuarterRestInk.Refusal e) {                refused = true;            }            check(refused && low.exhausted, "oneunder refusal");            check(                    low.workUsed <= low.workLimit && low.bytesUsed <= low.byteLimit,                    "atomic counters");        }    }    public static void main(String[] args) throws Exception {        Path p = Path.of(args[0]), matrix = Path.of(args[1]);        int qualified = 0;        for (String line : Files.readAllLines(p.resolve("helper-expected.txt"))) {            String[] v = line.split("\\|");            Input a = read(matrix.resolve(v[0] + ".bin"));            byte[] before = a.raw.clone();            var budget = new FaintQuarterRestInk.Budget(64_000_000, 64_000_000);            int l = Integer.parseInt(v[1]), r = Integer.parseInt(v[2]);            var proof = prove(a, l, r, budget);            boolean expected = Boolean.parseBoolean(v[3]);            check((proof != null) == expected, "reference " + v[0]);            check(Arrays.equals(before, a.raw), "raw unchanged");            if (proof != null) {                qualified++;                check(                        proof.l == Integer.parseInt(v[4])                                && proof.r == Integer.parseInt(v[5])                                && proof.t == Integer.parseInt(v[6])                                && proof.b == Integer.parseInt(v[7]),                        "exact reference box");                int count = 0;                for (byte b : proof.pixels) if (b != 0) count++;                check(count == Integer.parseInt(v[8]), "exact reference pixels");                quotas(a, l, r, proof, budget.workUsed, budget.bytesUsed);            }        }        System.out.println(                "PASS "                        + checks                        + " original helper assertions; qualifiedOriginal="                        + qualified                        + "; no source admission claim");    }}